css:
/* Плавное раскрытие FAQ на <details>. Цвета берутся из токенов дизайн-системы. */
.faq__list { display: grid; gap: 12px; max-width: 760px; margin-inline: auto; } /* одна колонка */
.faq__item {
  padding: 0; border: 1px solid var(--color-border, #e5e7eb); border-radius: 16px;
  background: var(--color-surface, #ffffff); color: var(--color-text, #111827);
} /* без overflow: hidden, внешней тени и transform — см. perf */
.faq__q {
  position: relative; display: flex; align-items: center; justify-content: space-between; gap: 16px;
  min-height: 48px; padding: 20px 24px; border-radius: inherit;
  font-weight: 600; line-height: 1.4; cursor: pointer; list-style: none;
}
.faq__q::-webkit-details-marker { display: none; }
.faq__item[open] > .faq__q { border-end-start-radius: 0; border-end-end-radius: 0; }
/* Подсветка при наведении — отдельный слой с opacity, а не смена background */
.faq__q::before {
  content: ""; position: absolute; inset: 0; border-radius: inherit; pointer-events: none;
  background: currentColor; opacity: 0; transition: opacity 150ms cubic-bezier(.2, 0, 0, 1);
}
@media (hover: hover) { .faq__q:hover::before { opacity: .05; } }
/* Рамка фокуса внутри вопроса: clip-path карточки во время анимации не срежет её */
.faq__q:focus-visible { outline: 3px solid var(--color-link, #1d4ed8); outline-offset: -3px; }
/* Значок «плюс → минус»: вертикальная черта поворачивается и ложится на горизонтальную */
.faq__icon { position: relative; flex: none; width: 20px; height: 20px; }
.faq__icon::before, .faq__icon::after {
  content: ""; position: absolute; inset: 9px 2px; border-radius: 2px; background: currentColor;
}
.faq__icon::after {
  transform: rotate(90deg);
  transition: transform 150ms cubic-bezier(.2, 0, 0, 1), opacity 150ms cubic-bezier(.2, 0, 0, 1);
}
.faq__item[open]:not(.is-closing) .faq__icon::after { transform: rotate(180deg); }
/* Ответ: без внешних отступов — скрипт меряет его высоту по рамке */
.faq__a { display: flow-root; margin: 0; padding: 0 24px 20px; color: var(--color-text-muted, #4b5563); line-height: 1.6; }
.faq__a > * { margin: 0 0 12px; }
.faq__a > :last-child { margin-bottom: 0; }
@media (max-width: 480px) {
  .faq__q { padding: 16px; }
  .faq__a { padding: 0 16px 16px; }
}
/* Без скрипта ответ всё равно проявляется; со скриптом эту анимацию перекрывает анимация из JS */
.faq__item[open] > .faq__a { animation: faq-in 200ms cubic-bezier(.2, 0, 0, 1); }
@keyframes faq-in { from { opacity: 0; transform: translateY(-6px); } }
@keyframes faq-fade { from { opacity: 0; } }
/* Контрастная тема Windows: фон псевдоэлементов браузер заменяет на Canvas, и значок пропал бы */
@media (forced-colors: active) { .faq__icon::before, .faq__icon::after { background: CanvasText; forced-color-adjust: none; } }
@media (prefers-reduced-motion: reduce) {
  /* Уровень 1 — убираем: рост карточки и сдвиг вопросов ниже (скрипт при этой настройке не вмешивается).
     Уровень 2 — смягчаем: ответ проявляется затуханием 150ms без сдвига, значок меняется затуханием без поворота.
     Уровень 3 — оставляем: рамку фокуса и подсветку при наведении. */
  .faq__item[open] > .faq__a { animation: faq-fade 150ms linear; }
  .faq__icon::after, .faq__item[open]:not(.is-closing) .faq__icon::after { transform: rotate(90deg); transition: opacity 150ms linear; }
  .faq__item[open] .faq__icon::after { opacity: 0; }
}

