// Подключать в конце <body> или с defer. Без скрипта и при «уменьшить движение» работает родной <details>.
(() => {
  const mq = matchMedia('(prefers-reduced-motion: reduce)'), EASE = 'cubic-bezier(.2,0,0,1)', EXIT = 'cubic-bezier(.3,0,1,1)';
  const k = h => Math.min(1.6, Math.max(0.8, 1 + Math.log2(Math.max(h, 1) / 100) * 0.3)); // длиннее ответ — дольше: 100px = 1x, 200px = 1.3x, 400px = 1.6x
  const below = d => { const out = []; // всё, что ниже пункта в потоке: соседи на каждом уровне до <body>
    for (let n = d; n && n !== document.body; n = n.parentElement)
      for (let s = n.nextElementSibling; s; s = s.nextElementSibling)
        if (s.getClientRects().length && !/fixed|sticky|absolute/.test(getComputedStyle(s).position)) out.push(s);
    return out.slice(0, 24);
  };
  let queue = Promise.resolve(), last = 0; // клики по очереди; last — время последнего: всё кончается за 400ms после него, иначе сдвиг уйдёт в CLS
  const run = d => {
    const open = !d.open, panel = d.querySelector(':scope > .faq__a'), left = 400 - (performance.now() - last);
    if (!panel || left < 80) return void (d.open = open); // очередь отстала — переключаем сразу, без анимации
    const els = below(d), t0 = els.map(e => e.getBoundingClientRect().top); // 1. запомнить
    if (open) d.open = true; // 2. изменить (закрываем только в конце, иначе ответ исчезнет сразу)
    const h = panel.getBoundingClientRect().height, r = getComputedStyle(d).borderBottomLeftRadius;
    const dy = open ? els.map((e, i) => t0[i] - e.getBoundingClientRect().top) : els.map(() => -h);
    const dur = Math.round(Math.min((open ? 260 : 200) * k(h), left)), o = { duration: dur, easing: EASE, fill: 'both' };
    const clip = y => `inset(0 0 ${y}px 0 round ${r})`, shift = y => `translateY(${y}px)`, move = y => `0 ${y}px`;
    d.classList.toggle('is-closing', !open); // значок меняется сразу, не дожидаясь конца
    const anims = [ // 3. анимировать разницу: clip-path карточки, opacity и transform ответа, translate всего ниже (composite 'add' — свой transform соседей не слетает)
      d.animate({ clipPath: open ? [clip(h), clip(0)] : [clip(0), clip(h)] }, o),
      open ? panel.animate({ opacity: [0, 1], transform: [shift(-6), 'none'] }, { ...o, delay: 60, duration: dur - 60 })
        : panel.animate({ opacity: [1, 0] }, { duration: Math.round(dur * 0.6), easing: EXIT, fill: 'both' }),
      ...els.map((e, i) => e.animate({ translate: open ? [move(dy[i]), move(0)] : [move(0), move(dy[i])] }, { ...o, composite: 'add' })),
    ];
    return Promise.all(anims.map(a => a.finished)).finally(() => {
      if (!open) d.open = false; // закрываем в том же кадре, где снимаем анимации, — без мигания
      d.classList.remove('is-closing');
      anims.forEach(a => a.cancel());
    });
  };
  document.addEventListener('click', e => {
    const s = e.target.closest?.('summary'), d = s && s.parentElement;
    if (e.defaultPrevented || !d || !d.matches('[data-accordion] > details') || mq.matches) return;
    e.preventDefault(); last = e.timeStamp; // Enter и Пробел на summary тоже приходят сюда как click
    queue = queue.then(() => run(d)).catch(() => {});
  });
})();
